package android.view;public class View {public static final int VISIBLE=0,GONE=8;Object tag;public void setTag(Object t){tag=t;}public Object getTag(){return tag;}public View findViewWithTag(Object t){return t.equals(tag)?this:null;}public boolean requestFocus(){return true;}public void setBackgroundColor(int c){}ViewGroup parent;int visibility;public ViewGroup getParent(){return parent;}public void setVisibility(int v){visibility=v;}public int getVisibility(){return visibility;}CharSequence desc;public void setContentDescription(CharSequence s){desc=s;}public CharSequence getContentDescription(){return desc;}public void setPadding(int a,int b,int c,int d){}public void setMinimumHeight(int n){}public void setFocusable(boolean b){}public void setBackground(android.graphics.drawable.GradientDrawable d){}public void setBackgroundTintList(android.content.res.ColorStateList c){}public interface OnClickListener {void onClick(View v);}public interface OnLongClickListener {boolean onLongClick(View v);}OnClickListener click;OnLongClickListener hold;public void setOnClickListener(OnClickListener c){click=c;}public void setOnLongClickListener(OnLongClickListener c){hold=c;}public boolean performClick(){if(click==null)return false;click.onClick(this);return true;}public boolean performLongClick(){return hold!=null&&hold.onLongClick(this);}}